package com.basiclab.iot.transform.runtime.service; import com.basiclab.iot.transform.core.domain.PipelineDef; import com.basiclab.iot.transform.runtime.dal.TransformRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class PipelineService { private final TransformRepository repository; public PipelineService(TransformRepository repository){this.repository=repository;} public Collection<PipelineDef> list(){return repository.listPipelines();} public PipelineDef get(String id){return repository.listPipelines().stream().filter(p -> id.equals(p.getId())).findFirst().orElse(null);} }